Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>
#define fst first
#define snd second
#define fore(i,a,b) for(int i=a,ThxDem=b;i<ThxDem;++i)
#define pb push_back
#define ALL(s) s.begin(),s.end()
#define FIN ios_base::sync_with_stdio(0);cin.tie(0);cout.tie(0)
#define SZ(s) int(s.size())
using namespace std;
typedef long long ll;
typedef pair<int,int> ii;

const int INF=1e9;
struct MCF {
	int n, m, k, t;
	vector<int> u,v,prio,curflow,prevedge,prevnode,pot;
	struct Edge {
		int to, f, cap, cost, rev;
	};
	vector<vector<Edge>> adj;
	MCF(int n):n(n),u(n),v(n),prio(n),curflow(n),prevedge(n),prevnode(n),pot(n),adj(n){}
	priority_queue<ll, vector<ll>, greater<ll> > q;
	inline void addEdge(int s, int t, int cap, int cost) {
		Edge a = {t, 0, cap, cost, SZ(adj[t])};
		Edge b = {s, 0, 0, -cost, SZ(adj[s])};
		adj[s].push_back(a);
		adj[t].push_back(b);
	}
	inline pair<int, int> minCostFlow(int s, int t) {
		int flow=0, flowCost=0;
		while(flow<INF) {
			q.push(s);
			fill(ALL(prio), INT_MAX);
			prio[s]=0;
			curflow[s]=INT_MAX;
			while(!q.empty()) {
				ll cur=q.top();
				int d=cur>>32, u=cur;
				q.pop();
				if(d!=prio[u])
					continue;
				for(int i=0; i<SZ(adj[u]); ++i) {
					Edge &e=adj[u][i];
					int v=e.to;
					if (e.cap<=e.f)
						continue;
					int nprio=prio[u]+e.cost+pot[u]-pot[v];
					if (prio[v]>nprio) {
						prio[v]=nprio;
						q.push(((ll)nprio<<32)+v);
						prevnode[v]=u;
						prevedge[v]=i;
						curflow[v]=min(curflow[u], e.cap-e.f);
					}
				}
			}
			if(prio[t]==INT_MAX)
				break;
			for(int i=0; i<n; ++i)
				pot[i]+=prio[i];
			int df=min(curflow[t], INF-flow);
			flow+=df;
			for(int v=t; v!=s; v=prevnode[v]) {
				Edge &e=adj[prevnode[v]][prevedge[v]];
				e.f+=df;
				adj[v][e.rev].f-=df;
				flowCost+=df*e.cost;
			}
		}
		return make_pair(flow, flowCost);
	}
};

int n,m,k,c,d;

int main(){
	scanf("%d%d%d%d%d",&n,&m,&k,&c,&d);
	MCF nt(6+107*n);
	fore(_,0,k){
		int x;
		scanf("%d",&x);x--;
		nt.addEdge(0,1+x,1,0);
	}
	fore(_,0,m){
		int x,y;
		scanf("%d%d",&x,&y);x--;y--;
		fore(i,0,105){
			fore(j,0,51){
				nt.addEdge(1+i*n+x,1+(i+1)*n+y,1,c+d*(2*j+1));
				nt.addEdge(1+i*n+y,1+(i+1)*n+x,1,c+d*(2*j+1));
			}
		}
	}
	fore(i,0,105)fore(j,0,n)nt.addEdge(1+i*n+j,1+(i+1)*n+j,51,c);
	fore(i,0,105)nt.addEdge(1+i*n,1+105*n,51,0);
	auto ans=nt.minCostFlow(0,1+105*n);
	printf("%d\n",ans.snd);
	return 0;
}

